"""crossbar_exact: parametric CadQuery model generated by stl2cad (exact mode, 2.5D).

The part is built along +z from 1 extrusion(s) and 1 cut(s), applied in order;
each is an outline in the xy plane between two levels. Units: mm.
Run:  python crossbar_exact.py [out.step]
"""

import math
import sys

from cadquery import Edge, Vector
from cadquery import func as cf

# ---- parameters ----------------------------------------------------------
z0 = -110.0    # level along z
z1 = 0.0    # level along z
hole_d = 2.0

DIR = (0, 0, 1)


def P(a, b):
    """Point (x, y) in the sketch plane (z = 0)."""
    return (a, b, 0)


def prism(outline, lo, hi):
    """Outline extruded from level lo to level hi."""
    body = cf.extrude(cf.face(outline), [(hi - lo) * c for c in DIR])
    return body.translate(Vector(*[lo * c for c in DIR]))


def hole(a, b, d, lo, hi):
    return prism(Edge.makeCircle(d / 2, P(a, b), DIR), lo, hi)


# ---- 1. extrusion: z -110.0 to 0.0 ------------------------------
outline_1 = cf.wire(
    cf.segment(P(-1.3489, 2.5), P(1.3489, 2.5)),
    cf.segment(P(1.3489, 2.5), P(1.4581, 2.5262)),
    cf.segment(P(1.4581, 2.5262), P(3.0161, 4.0726)),
    Edge.makeThreePointArc(P(3.0161, 4.0726), P(3.0835, 4.3066), P(2.84, 4.5)),
    cf.segment(P(2.84, 4.5), P(1.25, 4.5)),
    Edge.makeThreePointArc(P(1.25, 4.5), P(1.0893, 4.5585), P(1.0, 4.75)),
    cf.segment(P(1.0, 4.75), P(1.0, 5.75)),
    Edge.makeThreePointArc(P(1.0, 5.75), P(1.0585, 5.9107), P(1.25, 6.0)),
    cf.segment(P(1.25, 6.0), P(5.75, 6.0)),
    Edge.makeThreePointArc(P(5.75, 6.0), P(5.9107, 5.9415), P(6.0, 5.75)),
    cf.segment(P(6.0, 5.75), P(6.0, 1.25)),
    Edge.makeThreePointArc(P(6.0, 1.25), P(5.9415, 1.0893), P(5.75, 1.0)),
    cf.segment(P(5.75, 1.0), P(4.75, 1.0)),
    Edge.makeThreePointArc(P(4.75, 1.0), P(4.5893, 1.0585), P(4.5, 1.25)),
    cf.segment(P(4.5, 1.25), P(4.5, 2.84)),
    Edge.makeThreePointArc(P(4.5, 2.84), P(4.3849, 3.0505), P(4.073, 3.0166)),
    cf.segment(P(4.073, 3.0166), P(2.5646, 1.5044)),
    cf.segment(P(2.5646, 1.5044), P(2.5, 1.3989)),
    cf.segment(P(2.5, 1.3989), P(2.5, -1.3989)),
    cf.segment(P(2.5, -1.3989), P(2.5646, -1.5044)),
    cf.segment(P(2.5646, -1.5044), P(4.073, -3.0166)),
    Edge.makeThreePointArc(P(4.073, -3.0166), P(4.3849, -3.0505), P(4.5, -2.84)),
    cf.segment(P(4.5, -2.84), P(4.5, -1.25)),
    Edge.makeThreePointArc(P(4.5, -1.25), P(4.5893, -1.0585), P(4.75, -1.0)),
    cf.segment(P(4.75, -1.0), P(5.75, -1.0)),
    Edge.makeThreePointArc(P(5.75, -1.0), P(5.9415, -1.0893), P(6.0, -1.25)),
    cf.segment(P(6.0, -1.25), P(6.0, -5.75)),
    Edge.makeThreePointArc(P(6.0, -5.75), P(5.9107, -5.9415), P(5.75, -6.0)),
    cf.segment(P(5.75, -6.0), P(1.25, -6.0)),
    Edge.makeThreePointArc(P(1.25, -6.0), P(1.0585, -5.9107), P(1.0, -5.75)),
    cf.segment(P(1.0, -5.75), P(1.0, -4.75)),
    Edge.makeThreePointArc(P(1.0, -4.75), P(1.0893, -4.5585), P(1.25, -4.5)),
    cf.segment(P(1.25, -4.5), P(2.84, -4.5)),
    Edge.makeThreePointArc(P(2.84, -4.5), P(3.0835, -4.3066), P(3.0161, -4.0726)),
    cf.segment(P(3.0161, -4.0726), P(1.4581, -2.5262)),
    cf.segment(P(1.4581, -2.5262), P(1.3489, -2.5)),
    cf.segment(P(1.3489, -2.5), P(-1.3489, -2.5)),
    cf.segment(P(-1.3489, -2.5), P(-1.4581, -2.5262)),
    cf.segment(P(-1.4581, -2.5262), P(-3.0161, -4.0726)),
    Edge.makeThreePointArc(P(-3.0161, -4.0726), P(-3.0835, -4.3066), P(-2.84, -4.5)),
    cf.segment(P(-2.84, -4.5), P(-1.25, -4.5)),
    Edge.makeThreePointArc(P(-1.25, -4.5), P(-1.0893, -4.5585), P(-1.0, -4.75)),
    cf.segment(P(-1.0, -4.75), P(-1.0, -5.75)),
    Edge.makeThreePointArc(P(-1.0, -5.75), P(-1.0585, -5.9107), P(-1.25, -6.0)),
    cf.segment(P(-1.25, -6.0), P(-5.75, -6.0)),
    Edge.makeThreePointArc(P(-5.75, -6.0), P(-5.9107, -5.9415), P(-6.0, -5.75)),
    cf.segment(P(-6.0, -5.75), P(-6.0, -1.25)),
    Edge.makeThreePointArc(P(-6.0, -1.25), P(-5.9415, -1.0893), P(-5.75, -1.0)),
    cf.segment(P(-5.75, -1.0), P(-4.75, -1.0)),
    Edge.makeThreePointArc(P(-4.75, -1.0), P(-4.5893, -1.0585), P(-4.5, -1.25)),
    cf.segment(P(-4.5, -1.25), P(-4.5, -2.84)),
    Edge.makeThreePointArc(P(-4.5, -2.84), P(-4.3849, -3.0505), P(-4.073, -3.0166)),
    cf.segment(P(-4.073, -3.0166), P(-2.5646, -1.5044)),
    cf.segment(P(-2.5646, -1.5044), P(-2.5, -1.3989)),
    cf.segment(P(-2.5, -1.3989), P(-2.5, 1.3989)),
    cf.segment(P(-2.5, 1.3989), P(-2.5646, 1.5044)),
    cf.segment(P(-2.5646, 1.5044), P(-4.073, 3.0166)),
    Edge.makeThreePointArc(P(-4.073, 3.0166), P(-4.3849, 3.0505), P(-4.5, 2.84)),
    cf.segment(P(-4.5, 2.84), P(-4.5, 1.25)),
    Edge.makeThreePointArc(P(-4.5, 1.25), P(-4.5893, 1.0585), P(-4.75, 1.0)),
    cf.segment(P(-4.75, 1.0), P(-5.75, 1.0)),
    Edge.makeThreePointArc(P(-5.75, 1.0), P(-5.9415, 1.0893), P(-6.0, 1.25)),
    cf.segment(P(-6.0, 1.25), P(-6.0, 5.75)),
    Edge.makeThreePointArc(P(-6.0, 5.75), P(-5.9107, 5.9415), P(-5.75, 6.0)),
    cf.segment(P(-5.75, 6.0), P(-1.25, 6.0)),
    Edge.makeThreePointArc(P(-1.25, 6.0), P(-1.0585, 5.9107), P(-1.0, 5.75)),
    cf.segment(P(-1.0, 5.75), P(-1.0, 4.75)),
    Edge.makeThreePointArc(P(-1.0, 4.75), P(-1.0893, 4.5585), P(-1.25, 4.5)),
    cf.segment(P(-1.25, 4.5), P(-2.84, 4.5)),
    Edge.makeThreePointArc(P(-2.84, 4.5), P(-3.0835, 4.3066), P(-3.0161, 4.0726)),
    cf.segment(P(-3.0161, 4.0726), P(-1.4581, 2.5262)),
    cf.segment(P(-1.4581, 2.5262), P(-1.3489, 2.5)),
)
part = prism(outline_1, z0, z1)

# ---- round holes: (x, y, diameter, from, to) ------------------------
for a, b, d, lo, hi in [
    (0.0, 0.0, hole_d, z0, z1),
]:
    part = part - hole(a, b, d, lo, hi)

part = part.clean()

if __name__ == "__main__":
    part.exportStep(sys.argv[1] if len(sys.argv) > 1 else "crossbar_exact.step")
